<!DOCTYPE html>
<html lang="ko">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Gemma-4-31b-Bedrock Media Art</title>
    <style>
        :root {
            --bg-color: #05070a;
            --primary-color: #4285f4;
            --accent-color: #34a853;
            --text-color: #e8eaed;
            --font-family: 'Pretendard', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            background-color: var(--bg-color);
            color: var(--text-color);
            font-family: var(--font-family);
            overflow: hidden;
            height: 100vh;
            display: flex;
            justify-content: center;
            align-items: center;
            touch-action: none;
        }

        /* Accessibility: High contrast and focus states */
        body:focus-visible {
            outline: 3px solid var(--primary-color);
        }

        canvas {
            position: absolute;
            top: 0;
            left: 0;
            z-index: 1;
            cursor: crosshair;
        }

        .ui-overlay {
            position: relative;
            z-index: 10;
            text-align: center;
            pointer-events: none;
            user-select: none;
            padding: 20px;
            max-width: 90vw;
        }

        h1 {
            font-size: clamp(1.5rem, 5vw, 3rem);
            font-weight: 300;
            letter-spacing: 0.2em;
            margin-bottom: 1rem;
            opacity: 0.9;
            text-shadow: 0 0 20px rgba(66, 133, 244, 0.5);
        }

        .model-id {
            font-family: 'Courier New', Courier, monospace;
            font-size: clamp(0.8rem, 3vw, 1.2rem);
            color: var(--primary-color);
            background: rgba(66, 133, 244, 0.1);
            padding: 8px 16px;
            border-radius: 4px;
            border: 1px solid rgba(66, 133, 244, 0.3);
            display: inline-block;
        }

        .instruction {
            margin-top: 2rem;
            font-size: 0.9rem;
            opacity: 0.6;
            transition: opacity 0.3s ease;
        }

        /* Reduced motion support */
        @media (prefers-reduced-motion: reduce) {
            .particle {
                animation: none !important;
                transition: none !important;
            }
        }
    </style>
</head>
<body>

    <canvas id="artCanvas"></canvas>

    <div class="ui-overlay" role="main">
        <h1>Neural Resonance</h1>
        <div class="model-id" aria-label="Model Identifier">gemma-4-31b-bedrock</div>
        <div class="instruction">
            화면을 터치하거나 마우스를 움직여 신경망의 연결을 깨우세요.
        </div>
    </div>

    <script>
        /**
         * Media Art Concept: "The Latent Web"
         * 
         * This piece visualizes the LLM's internal world as a dynamic, 
         * interconnected network of nodes. Users act as "prompts" or "queries",
         * triggering ripples of activation across the latent space.
         */

        const canvas = document.getElementById('artCanvas');
        const ctx = canvas.getContext('2d');
        let width, height;
        let particles = [];
        let mouse = { x: -1000, y: -1000, active: false };

        const CONFIG = {
            particleCount: 120,
            connectionDistance: 150,
            baseNodeRadius: 2,
            interactionRadius: 200,
            colors: ['#4285f4', '#34a853', '#fbbc05', '#ea4335']
        };

        class Particle {
            constructor() {
                this.init();
            }

            init() {
                this.x = Math.random() * width;
                this.y = Math.random() * height;
                this.vx = (Math.random() - 0.5) * 0.5;
                this.vy = (Math.random() - 0.5) * 0.5;
                this.radius = Math.random() * CONFIG.baseNodeRadius + 1;
                this.color = CONFIG.colors[Math.floor(Math.random() * CONFIG.colors.length)];
                this.baseColor = this.color;
            }

            update() {
                this.x += this.vx;
                this.y += this.vy;

                // Bounce off walls
                if (this.x < 0 || this.x > width) this.vx *= -1;
                if (this.y < 0 || this.y > height) this.vy *= -1;

                // Interaction logic
                const dx = mouse.x - this.x;
                const dy = mouse.y - this.y;
                const distance = Math.sqrt(dx * dx + dy * dy);

                if (distance < CONFIG.interactionRadius) {
                    const force = (CONFIG.interactionRadius - distance) / CONFIG.interactionRadius;
                    this.x -= dx * force * 0.02;
                    this.y -= dy * force * 0.02;
                    this.radius = CONFIG.baseNodeRadius * 2 + force * 3;
                } else {
                    this.radius = Math.max(this.radius - 0.1, CONFIG.baseNodeRadius);
                }
            }

            draw() {
                ctx.beginPath();
                ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
                ctx.fillStyle = this.color;
                ctx.fill();
            }
        }

        function setup() {
            width = window.innerWidth;
            height = window.innerHeight;
            canvas.width = width;
            canvas.height = height;

            particles = [];
            for (let i = 0; i < CONFIG.particleCount; i++) {
                particles.push(new Particle());
            }
        }

        function drawConnections() {
            ctx.lineWidth = 0.5;
            for (let i = 0; i < particles.length; i++) {
                for (let j = i + 1; j < particles.length; j++) {
                    const p1 = particles[i];
                    const p2 = particles[j];
                    const dist = Math.hypot(p1.x - p2.x, p1.y - p2.y);

                    if (dist < CONFIG.connectionDistance) {
                        const opacity = 1 - (dist / CONFIG.connectionDistance);
                        ctx.strokeStyle = `rgba(66, 133, 244, ${opacity * 0.4})`;
                        ctx.beginPath();
                        ctx.moveTo(p1.x, p1.y);
                        ctx.lineTo(p2.x, p2.y);
                        ctx.stroke();
                    }
                }
            }
        }

        function animate() {
            // Subtle trail effect for fluidity
            ctx.fillStyle = 'rgba(5, 7, 10, 0.2)';
            ctx.fillRect(0, 0, width, height);

            drawConnections();

            particles.forEach(p => {
                p.update();
                p.draw();
            });

            requestAnimationFrame(animate);
        }

        // Interaction Handlers
        function handleMove(e) {
            const touch = e.touches ? e.touches[0] : e;
            mouse.x = touch.clientX;
            mouse.y = touch.clientY;
            mouse.active = true;
        }

        window.addEventListener('mousemove', handleMove);
        window.addEventListener('touchmove', (e) => {
            handleMove(e);
            e.preventDefault(); // Prevent scrolling while interacting
        }, { passive: false });

        window.addEventListener('resize', setup);

        // Accessibility: Keyboard navigation
        window.addEventListener('keydown', (e) => {
            // Move "phantom" mouse with arrow keys for accessibility
            const step = 30;
            if (e.key === 'ArrowUp') mouse.y -= step;
            if (e.key === 'ArrowDown') mouse.y += step;
            if (e.key === 'ArrowLeft') mouse.x -= step;
            if (e.key === 'ArrowRight') mouse.x += step;
        });

        // Initialize
        setup();
        animate();

    </script>
</body>
</html>
